import { Controller, Get, Post, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const CARD_TYPES = ['법인', '개인', '사업용'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 카드번호 암호화 키는 DB 설정값(app.card_key)에서 읽는다. 키 값은 코드에 두지 않는다.

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function idOf(value: unknown, label: string): number {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return value;
  }
  if (typeof value === 'string' && /^[0-9]+$/.test(value) && Number(value) > 0) {
    return Number(value);
  }
  throw invalid(label + ' 값을 확인해 주세요.');
}

function optText(value: unknown, label: string, max: number): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'string' || value.length > max) {
    throw invalid(label + ' 값을 확인해 주세요.');
  }
  return value;
}

function pagingOf(q: Record<string, unknown>): { page: number; size: number } {
  const rawPage = q['page'] === undefined || q['page'] === '' ? 0 : Number(q['page']);
  const rawSize = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : Number(q['size']);
  if (!Number.isInteger(rawPage) || rawPage < 0 || !Number.isInteger(rawSize) || rawSize < 1) {
    throw invalid('page와 size 값을 확인해 주세요.');
  }
  return { page: rawPage, size: Math.min(rawSize, MAX_SIZE) };
}

@Controller('api/v1')
export class FnSfr00206Controller {
  @Get('/credit-cards')
  async listCreditCards(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const { page, size } = pagingOf(q);
    const cardType = optText(q['cardType'], '카드 유형', 20);
    if (cardType !== null && !CARD_TYPES.includes(cardType)) {
      throw invalid('카드 유형은 법인, 개인, 사업용 중 하나여야 합니다.');
    }
    return transaction(async (db) => {
      const params = { cardType, size, offset: page * size };
      const items = await db.query(
        `SELECT credit_card_id AS "creditCardId",
                card_type AS "cardType",
                card_number_last4 AS "cardNumberLast4",
                card_name AS "cardName",
                issuer_name AS "issuerName",
                to_char(expiry_date, 'YYYY-MM-DD') AS "expiryDate"
           FROM credit_card
          WHERE (CAST(:cardType AS text) IS NULL OR card_type = CAST(:cardType AS text))
          ORDER BY credit_card_id DESC
          LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM credit_card
          WHERE (CAST(:cardType AS text) IS NULL OR card_type = CAST(:cardType AS text))`,
        { cardType },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/credit-cards')
  @HttpCode(200)
  async createCreditCard(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const cardType = data['cardType'];
    if (typeof cardType !== 'string' || !CARD_TYPES.includes(cardType)) {
      throw invalid('카드 유형은 법인, 개인, 사업용 중 하나여야 합니다.');
    }
    const rawNumber = data['cardNumber'];
    if (typeof rawNumber !== 'string' || rawNumber.trim() === '') {
      throw invalid('카드번호를 입력해 주세요.');
    }
    const cardNumber = rawNumber.replace(/[-\s]/g, '');
    if (!/^[0-9]{4,30}$/.test(cardNumber)) {
      throw invalid('카드번호는 숫자로 입력해 주세요.');
    }
    const last4 = cardNumber.slice(-4);
    const cardName = optText(data['cardName'], '카드명', 100);
    const issuerName = optText(data['issuerName'], '카드사명', 100);
    const expiryDate = optText(data['expiryDate'], '유효기간 만료일', 10);
    if (expiryDate !== null && !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(expiryDate)) {
      throw invalid('유효기간 만료일은 YYYY-MM-DD 형식이어야 합니다.');
    }
    return transaction(async (db) => {
      const dup = await db.query(
        `SELECT credit_card_id
           FROM credit_card
          WHERE card_number_last4 = :last4
            AND pgp_sym_decrypt(decode(card_number_enc, 'base64'), current_setting('app.card_key', true)) = :cardNumber`,
        { last4, cardNumber },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'CREDIT_CARD_DUPLICATED', '이미 등록된 카드번호입니다.');
      }
      const rows = await db.query(
        `INSERT INTO credit_card
           (card_type, card_number_enc, card_number_last4, card_name, issuer_name, expiry_date, created_at, updated_at)
         VALUES
           (:cardType,
            encode(pgp_sym_encrypt(:cardNumber, current_setting('app.card_key', true)), 'base64'),
            :last4, :cardName, :issuerName, CAST(:expiryDate AS date), now(), now())
         RETURNING credit_card_id AS "creditCardId"`,
        { cardType, cardNumber, last4, cardName, issuerName, expiryDate },
      );
      return { creditCardId: Number(rows[0].creditCardId) };
    });
  }

  @Get('/credit-card-permissions')
  async listCreditCardPermissions(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query) as Record<string, unknown>;
    const { page, size } = pagingOf(q);
    const creditCardId = idOf(q['creditCardId'], '신용카드');
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT credit_card_permission_id AS "creditCardPermissionId",
                credit_card_id AS "creditCardId",
                employee_id AS "employeeId"
           FROM credit_card_permission
          WHERE credit_card_id = CAST(:creditCardId AS bigint)
          ORDER BY credit_card_permission_id
          LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        { creditCardId, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total"
           FROM credit_card_permission
          WHERE credit_card_id = CAST(:creditCardId AS bigint)`,
        { creditCardId },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/credit-card-permissions')
  @HttpCode(200)
  async createCreditCardPermission(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body) as Record<string, unknown>;
    const creditCardId = idOf(data['creditCardId'], '신용카드');
    const employeeId = idOf(data['employeeId'], '임직원');
    return transaction(async (db) => {
      const cards = await db.query(
        `SELECT credit_card_id FROM credit_card WHERE credit_card_id = CAST(:creditCardId AS bigint)`,
        { creditCardId },
      );
      if (cards.length === 0) {
        throw new ApiError(404, 'CREDIT_CARD_NOT_FOUND', '신용카드를 찾을 수 없습니다.');
      }
      const employees = await db.query(
        `SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)`,
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '임직원을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        `SELECT credit_card_permission_id
           FROM credit_card_permission
          WHERE credit_card_id = CAST(:creditCardId AS bigint)
            AND employee_id = CAST(:employeeId AS bigint)`,
        { creditCardId, employeeId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'CREDIT_CARD_PERMISSION_DUPLICATED', '이미 조회 권한이 설정된 임직원입니다.');
      }
      const rows = await db.query(
        `INSERT INTO credit_card_permission (credit_card_id, employee_id, created_at, updated_at)
         VALUES (CAST(:creditCardId AS bigint), CAST(:employeeId AS bigint), now(), now())
         RETURNING credit_card_permission_id AS "creditCardPermissionId"`,
        { creditCardId, employeeId },
      );
      return { creditCardPermissionId: Number(rows[0].creditCardPermissionId) };
    });
  }

  @Delete('/credit-card-permissions/:creditCardPermissionId')
  async deleteCreditCardPermission(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const permissionId = idOf(req.params['creditCardPermissionId'], '신용카드 조회 권한');
    return transaction(async (db) => {
      const changed = await db.execute(
        `DELETE FROM credit_card_permission
          WHERE credit_card_permission_id = CAST(:permissionId AS bigint)`,
        { permissionId },
      );
      if (changed === 0) {
        throw new ApiError(404, 'CREDIT_CARD_PERMISSION_NOT_FOUND', '조회 권한 설정을 찾을 수 없습니다.');
      }
      return {};
    });
  }
}

