import { useState } from 'react';
import {
  call,
  useData,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  Filters,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  DateText,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const CARD_TYPE_OPTIONS: [string, string][] = [
  ['법인', '법인'],
  ['개인', '개인'],
  ['사업용', '사업용'],
];
const SIZE = 20;

function PermissionSection({ role, card, notify }: { role: string; card: Row; notify: (text: string) => void }) {
  const [adding, setAdding] = useState(false);
  const [removing, setRemoving] = useState<Row | null>(null);
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/credit-card-permissions', role, undefined, { creditCardId: card.creditCardId, size: 200 }),
    [card.creditCardId],
  );
  const rows = data ? data.items : [];

  return (
    <section className="box">
      <h2>조회 권한 대상</h2>
      {error ? <ErrorText text={error} /> : null}
      <Band total={data ? data.total : 0}>
        <button className="ghost" onClick={() => { setEmployeeId(''); setAdding(true); }}>조회 권한 추가</button>
      </Band>
      <DataTable
        columns={[
          { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
          {
            key: 'creditCardPermissionId',
            label: '관리',
            render: (r) => <button className="ghost" onClick={() => setRemoving(r)}>권한 삭제</button>,
          },
        ]}
        rows={rows}
        empty="아직 조회 권한을 설정한 임직원이 없습니다. 조회 권한 추가 버튼으로 설정해 주세요."
      />
      {adding ? (
        <Drawer title="조회 권한 추가" onClose={() => setAdding(false)}>
          <Form
            submit="추가"
            onSubmit={async () => {
              if (employeeId === '') {
                throw new Error('임직원을 선택해 주세요.');
              }
              await call('POST', '/credit-card-permissions', role, { creditCardId: card.creditCardId, employeeId });
              notify('조회 권한을 추가했습니다.');
              setAdding(false);
              reload();
            }}
          >
            <Field label="임직원" required wide>
              <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {removing ? (
        <Drawer title="조회 권한 삭제" onClose={() => setRemoving(null)}>
          <Form
            submit="삭제"
            danger
            note="삭제하면 해당 임직원은 이 카드 정보를 더 이상 조회할 수 없습니다."
            onSubmit={async () => {
              await call('DELETE', '/credit-card-permissions/' + String(removing.creditCardPermissionId), role);
              notify('조회 권한을 삭제했습니다.');
              setRemoving(null);
              reload();
            }}
          >
            <Pairs items={[['임직원', <RefName table="employee" role={role} value={removing.employeeId} />]]} />
          </Form>
        </Drawer>
      ) : null}
    </section>
  );
}

export default function FnSfr00206Page({ role, notify }: PageProps) {
  const [typeDraft, setTypeDraft] = useState('');
  const [cardType, setCardType] = useState('');
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState<Row>({ cardType: '', cardNumber: '', cardName: '', issuerName: '', expiryDate: '' });

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/credit-cards', role, undefined, { cardType, page, size: SIZE }),
    [cardType, page],
  );

  function setField(key: string, value: unknown) {
    setForm({ ...form, [key]: value });
  }

  if (selected) {
    return (
      <div className="doc">
        <button className="ghost" onClick={() => setSelected(null)}>목록으로 돌아가기</button>
        <section className="box">
          <h2>카드 정보</h2>
          <Pairs
            items={[
              ['카드 유형', String(selected.cardType)],
              ['카드번호 끝 4자리', String(selected.cardNumberLast4 ?? '')],
              ['카드명', String(selected.cardName ?? '')],
              ['카드사명', String(selected.issuerName ?? '')],
              ['유효기간 만료일', <DateText value={selected.expiryDate} />],
            ]}
          />
        </section>
        <PermissionSection role={role} card={selected} notify={notify} />
      </div>
    );
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>신용카드 관리</h2>
        <Filters
          onSearch={() => { setPage(0); setCardType(typeDraft); }}
          onReset={() => { setTypeDraft(''); setCardType(''); setPage(0); }}
        >
          <Field label="카드 유형">
            <Select value={typeDraft} onChange={setTypeDraft} options={CARD_TYPE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0}>
          <button
            onClick={() => {
              setForm({ cardType: '', cardNumber: '', cardName: '', issuerName: '', expiryDate: '' });
              setCreating(true);
            }}
          >
            카드 등록
          </button>
        </Band>
        <DataTable
          columns={[
            { key: 'cardType', label: '카드 유형' },
            { key: 'cardName', label: '카드명' },
            { key: 'issuerName', label: '카드사명' },
            { key: 'cardNumberLast4', label: '카드번호 끝 4자리', render: (r) => <span>{'**** ' + String(r.cardNumberLast4 ?? '')}</span> },
            { key: 'expiryDate', label: '유효기간 만료일', render: (r) => <DateText value={r.expiryDate} /> },
          ]}
          rows={data ? data.items : []}
          onRowClick={(r) => setSelected(r)}
          empty="아직 등록한 카드가 없습니다. 카드 등록 버튼으로 첫 카드를 등록해 주세요."
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {creating ? (
        <Drawer title="카드 등록" onClose={() => setCreating(false)}>
          <Form
            submit="등록"
            note="카드번호는 암호화하여 저장하며 화면에는 끝 4자리만 표시합니다."
            onSubmit={async () => {
              if (!form.cardType) {
                throw new Error('카드 유형을 선택해 주세요.');
              }
              if (!String(form.cardNumber ?? '').trim()) {
                throw new Error('카드번호를 입력해 주세요.');
              }
              await call('POST', '/credit-cards', role, {
                cardType: form.cardType,
                cardNumber: form.cardNumber,
                cardName: form.cardName,
                issuerName: form.issuerName,
                expiryDate: form.expiryDate,
              });
              notify('신용카드를 등록했습니다.');
              setCreating(false);
              setPage(0);
              reload();
            }}
          >
            <Field label="카드 유형" required>
              <Select value={form.cardType} onChange={(v) => setField('cardType', v)} options={CARD_TYPE_OPTIONS} />
            </Field>
            <Field label="평문 카드번호" required hint="숫자만 입력하며 하이픈은 제외됩니다.">
              <TextInput value={form.cardNumber} onChange={(v) => setField('cardNumber', v)} />
            </Field>
            <Field label="카드명">
              <TextInput value={form.cardName} onChange={(v) => setField('cardName', v)} />
            </Field>
            <Field label="카드사명">
              <TextInput value={form.issuerName} onChange={(v) => setField('issuerName', v)} />
            </Field>
            <Field label="유효기간 만료일">
              <DateInput value={form.expiryDate} onChange={(v) => setField('expiryDate', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
